.order-controls { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin: -4px 0 16px; }
.order-controls .secondary { padding: 8px 13px; min-height: 42px; font-size: .77rem; }
.fixed-suffix { display: inline-flex; align-items: center; padding: 8px 11px; border-radius: 9px; font-size: .88rem; background: #f2f2eb; border: 1px dashed #d6d9ca; color: var(--muted); }
.candidate { margin: 0 0 17px; padding: 11px 13px; background: #f2f7f3; border: 1px solid #dde9df; border-radius: 10px; }
.candidate-label { display: block; font-size: .63rem; color: var(--muted); margin-bottom: 3px; }
.candidate-name { display: block; font-size: .97rem; font-weight: 700; overflow-wrap: anywhere; }
.repair-actions { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.repair-actions .primary { min-width: 150px; }
.check-helper { color: var(--muted); font-size: .67rem; margin: 10px 0 0; }
.feedback { margin-top: 17px; padding: 13px 14px; border: 1px solid #ead0b9; border-radius: 12px; background: #fcf0e4; font-size: .81rem; color: #785132; }
.feedback:empty { display: none; }
.feedback p { margin-bottom: 0; }
.feedback.is-success { background: var(--mint); border-color: #bfd9ca; color: var(--ink); }
.success-title { display: block; font-size: .91rem; margin-bottom: 6px; }
.success-name { display: block; font-size: 1.09rem; font-weight: 750; margin-bottom: 7px; overflow-wrap: anywhere; }
.success-explanation { margin: 0; }
.round-next { display: flex; justify-content: flex-end; margin-top: 16px; }
.session-row { display: flex; align-items: center; justify-content: space-between; gap: 14px; margin-top: 18px; color: var(--muted); font-size: .69rem; }
.session-row .quiet { font-size: .69rem; min-height: 40px; padding: 7px 10px; }

/* End of a session */
.results { max-width: 840px; margin: 18px auto 0; }
.results-hero { text-align: center; padding: 0 10px 22px; }
.results-seal { width: 65px; height: 65px; display: grid; place-items: center; background: var(--mint); border: 1px solid #c4dece; border-radius: 22px; margin: 0 auto 20px; font-size: 1.7rem; transform: rotate(-7deg); }
.results-hero h1 { font-size: clamp(2rem, 4vw, 3rem); margin-bottom: 14px; }
.results-hero p { color: var(--muted); max-width: 620px; margin: 0 auto; font-size: .91rem; }
.results-stats { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 13px; margin: 6px 0 25px; }
.stat-card { border: 1px solid var(--line); border-radius: 18px; background: white; padding: 20px 16px; text-align: center; }
.stat-card:first-child { background: var(--mint); border-color: #c9ddcf; }
.stat-card:nth-child(2) { background: #fbefdf; border-color: #e9d6bc; }
.stat-number { display: block; font-size: 2.3rem; line-height: 1.1; font-weight: 750; letter-spacing: -.05em; margin-bottom: 9px; }
.stat-label { display: block; font-size: .75rem; font-weight: 650; line-height: 1.45; }
.results-detail { border: 1px solid var(--line); border-radius: 18px; overflow: hidden; background: white; }
.results-detail h2 { font-size: .9rem; padding: 17px 20px; background: #f4f6ef; margin: 0; border-bottom: 1px solid var(--line); }
.results-list { list-style: none; padding: 0; margin: 0; }
.result-item { display: grid; grid-template-columns: 28px 1fr; gap: 12px; align-items: start; padding: 15px 20px; }
.result-item + .result-item { border-top: 1px solid #e8ece5; }
.result-check { display: grid; place-items: center; height: 26px; width: 26px; background: var(--mint); border-radius: 9px; font-size: .8rem; font-weight: 700; }
.result-name { display: block; font-size: .86rem; font-weight: 700; overflow-wrap: anywhere; }
.result-objective { display: block; font-size: .69rem; color: var(--muted); margin-top: 2px; }
.results-note { color: var(--muted); font-size: .72rem; margin: 15px 0 22px; text-align: center; }
.results-actions { display: flex; flex-wrap: wrap; gap: 12px; justify-content: center; }
.site-footer { max-width: 1176px; margin: 0 auto; border-top: 1px solid var(--line); padding: 19px 0 24px; display: flex; justify-content: space-between; gap: 16px; color: var(--muted); font-size: .65rem; }
.confirm-dialog { width: calc(100% - 36px); max-width: 450px; border: 1px solid #c6d9cd; border-radius: 20px; padding: 25px; background: var(--paper); color: var(--ink); }
.confirm-dialog::backdrop { background: #183e4299; }
.confirm-dialog h2 { margin-bottom: 10px; }
.confirm-dialog p { font-size: .88rem; color: var(--muted); }
.confirm-actions { display: flex; flex-wrap: wrap; gap: 9px; margin-top: 20px; }
.zoom-dialog { width: calc(100% - 32px); max-width: 1050px; max-height: calc(100dvh - 32px); border: 1px solid #c6d9cd; border-radius: 20px; padding: 20px; background: var(--paper); color: var(--ink); }
.zoom-dialog::backdrop { background: #183e4299; }
.zoom-heading { display: flex; justify-content: space-between; align-items: center; gap: 15px; }
.zoom-heading h2 { font-size: 1rem; margin: 0; }
.zoom-dialog p { color: var(--muted); font-size: .76rem; margin: 12px 0; }
.zoom-viewport { max-height: calc(100dvh - 210px); overflow: auto; overscroll-behavior: contain; border: 1px solid var(--line); background: #fff; border-radius: 10px; padding: 20px; }
.zoom-image { display: block; width: auto; max-width: none; height: auto; margin: auto; }

@media (min-width: 1500px) {
  .intro { padding-top: 65px; padding-bottom: 70px; }
}
@media (max-width: 900px) {
  .header-label { display: none; }
  .exit-link { margin-left: auto; }
  .intro { gap: 30px; }
  .intro-art { padding: 19px; min-height: 365px; }
  .intro-how { gap: 18px; }
  .bench { grid-template-columns: .95fr 1.1fr; gap: 16px; }
  .repair-card { padding: 18px; }
  .diagram-stage { min-height: 210px; }
  .site-footer { margin-left: 32px; margin-right: 32px; }
}
@media (max-width: 700px) {
  .game-root { padding: 24px 22px 34px; }
  .intro { grid-template-columns: 1fr; gap: 33px; padding: 18px 0 28px; }
  .intro-copy h1 { font-size: 2.9rem; max-width: 560px; }
  .intro-description { font-size: .97rem; max-width: none; }
  .intro-art { min-height: 0; max-width: 500px; width: 100%; margin: 0 auto; }
  .art-sheet svg { height: 115px; }
  .art-header { margin-bottom: 13px; }
  .art-tabs { margin-top: 19px; }
  .intro-how { gap: 22px; grid-template-columns: 1fr; }
  .how-item { gap: 14px; }
  .how-item h2 { margin-bottom: 3px; }
  .bench { grid-template-columns: 1fr; gap: 16px; }
  .diagram-stage { min-height: 190px; }
  .round-topbar { margin-bottom: 22px; }
  .round-topbar .eyebrow { font-size: .57rem; letter-spacing: .09em; }
  .progress { gap: 5px; }
  .progress li { gap: 5px; }
  .progress li + li::before { width: 9px; }
  .progress-dot { min-width: 24px; height: 24px; font-size: .64rem; }
  .round-heading { margin-bottom: 17px; }
  .round-heading p { font-size: .85rem; }
  .round-heading h1 { font-size: 1.9rem; }
  .compact-steps { gap: 6px 12px; font-size: .66rem; margin-bottom: 18px; }
  .session-row { align-items: flex-start; }
  .results { margin-top: 8px; }
  .site-footer { margin-left: 22px; margin-right: 22px; flex-direction: column; gap: 6px; }
}
@media (max-width: 430px) {
  .header-inner { padding: 12px 18px; gap: 12px; }
  .brand { width: 190px; max-width: 66%; }
  .exit-link { font-size: .72rem; padding: 7px 12px; gap: 6px; }
  .game-root { padding: 23px 18px 30px; }
  .intro-copy h1 { font-size: 2.6rem; letter-spacing: -.05em; }
  .intro-description { margin-bottom: 20px; }
  .intro-badges { gap: 6px; margin-bottom: 23px; }
  .intro-badges span { font-size: .65rem; padding: 4px 9px; }
  .intro-start { width: 100%; }
  .intro-art { padding: 17px; border-radius: 23px; }
  .art-stamp { width: 57px; height: 57px; right: -5px; top: -16px; font-size: 1.35rem; border-radius: 18px; }
  .art-tabs { gap: 5px; }
  .art-tabs span { padding: 8px 10px; font-size: .7rem; }
  .round-topbar { align-items: flex-start; gap: 8px; }
  .round-topbar .eyebrow { max-width: 98px; padding-top: 4px; }
  .progress li + li::before { width: 5px; }
  .progress, .progress li { gap: 4px; }
  .progress-dot { min-width: 23px; height: 23px; }
  .card-heading { padding: 14px 16px; }
  .diagram-figure { padding: 13px 11px 11px; }
  .diagram-stage { min-height: 172px; }
  .diagram-tools { gap: 4px; }
  .diagram-tools > span { display: none; }
  .repair-card { padding: 17px; }
  .broken-name { padding: 11px; margin-bottom: 18px; }
  .part-button { padding: 9px 11px; font-size: .89rem; }
  .choice-button { font-size: .79rem; padding: 8px 10px; }
  .repair-actions .primary { flex: 1 1 auto; min-width: 140px; }
  .repair-actions .quiet { padding: 9px; font-size: .73rem; }
  .session-row { font-size: .63rem; gap: 8px; }
  .session-row .quiet { font-size: .63rem; padding: 6px 7px; }
  .results-stats { gap: 7px; margin-bottom: 20px; }
  .stat-card { padding: 17px 8px; border-radius: 13px; }
  .stat-number { font-size: 2rem; }
  .stat-label { font-size: .64rem; }
  .result-item { padding: 13px; gap: 9px; grid-template-columns: 24px 1fr; }
  .result-check { width: 24px; height: 24px; }
  .results-actions .primary, .results-actions .secondary { width: 100%; }
  .site-footer { margin-left: 18px; margin-right: 18px; font-size: .59rem; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; animation: none !important; transition: none !important; }
}
